CREATE OR REPLACE FUNCTION public.execution_gateway_policy_update_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    expected_actor UUID;
BEGIN
    expected_actor := COALESCE(
        NULLIF(to_jsonb(NEW) ->> 'approved_by_user_id', '')::UUID,
        NULLIF(to_jsonb(NEW) ->> 'updated_by_user_id', '')::UUID
    );
    IF OLD.audit_event_id IS NOT DISTINCT FROM NEW.audit_event_id
       OR NEW.updated_at <= OLD.updated_at THEN
        RAISE EXCEPTION 'execution gateway policy update requires a new audit event';
    END IF;
    IF NOT EXISTS (
        SELECT 1
        FROM execution_gateway_audit_events AS audit
        WHERE audit.event_id = NEW.audit_event_id
          AND audit.decision = 'accepted'
          AND audit.actor_user_id = expected_actor
          AND audit.created_at = NEW.updated_at
    ) THEN
        RAISE EXCEPTION 'execution gateway policy update audit binding is invalid';
    END IF;
    RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.identity_bind_browser_device(p_session uuid, p_key text, p_label text, p_now timestamp with time zone, p_device uuid)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_owner UUID;
    v_session identity_sessions%ROWTYPE;
    v_device UUID;
BEGIN
    SELECT user_id INTO v_owner FROM identity_sessions WHERE session_id = p_session;
    IF v_owner IS NULL THEN RAISE EXCEPTION 'inactive_session'; END IF;
    PERFORM 1 FROM identity_users WHERE user_id = v_owner FOR UPDATE;
    SELECT * INTO v_session FROM identity_sessions WHERE session_id = p_session FOR UPDATE;
    IF v_session.revoked_at IS NOT NULL OR v_session.idle_expires_at <= p_now
       OR v_session.absolute_expires_at <= p_now THEN
        RAISE EXCEPTION 'inactive_session';
    END IF;
    IF v_session.device_id IS NOT NULL THEN RETURN v_session.device_id; END IF;
    INSERT INTO identity_browser_devices(device_id, user_id, device_key, label, current_session_id)
    VALUES (p_device, v_owner, p_key, p_label, p_session)
    ON CONFLICT (user_id, device_key) DO UPDATE
        SET label = EXCLUDED.label, current_session_id = EXCLUDED.current_session_id
    RETURNING device_id INTO v_device;
    UPDATE identity_sessions SET revoked_at = GREATEST(p_now, created_at)
        WHERE user_id = v_owner AND device_id = v_device
          AND session_id <> p_session AND revoked_at IS NULL;
    UPDATE identity_sessions SET device_id = v_device, last_seen_at = GREATEST(last_seen_at, p_now)
        WHERE session_id = p_session;
    RETURN v_device;
END;
$function$

CREATE OR REPLACE FUNCTION public.job_runtime_attempts_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.organization_id IS DISTINCT FROM OLD.organization_id
       OR NEW.job_id IS DISTINCT FROM OLD.job_id
       OR NEW.attempt_id IS DISTINCT FROM OLD.attempt_id
       OR NEW.attempt_number IS DISTINCT FROM OLD.attempt_number
       OR NEW.envelope_digest IS DISTINCT FROM OLD.envelope_digest
       OR NEW.image_digest IS DISTINCT FROM OLD.image_digest
       OR NEW.envelope IS DISTINCT FROM OLD.envelope
       OR NEW.deadline IS DISTINCT FROM OLD.deadline THEN
        RAISE EXCEPTION 'job attempt envelope and identity are immutable';
    END IF;
    IF OLD.worker_id IS NOT NULL AND NEW.worker_id IS DISTINCT FROM OLD.worker_id THEN
        RAISE EXCEPTION 'job attempt worker identity is immutable';
    END IF;
    IF OLD.claimed_at IS NOT NULL AND NEW.claimed_at IS DISTINCT FROM OLD.claimed_at THEN
        RAISE EXCEPTION 'job attempt claim timestamp is immutable';
    END IF;
    IF OLD.result IS NOT NULL AND NEW.result IS DISTINCT FROM OLD.result THEN
        RAISE EXCEPTION 'job attempt result is immutable';
    END IF;
    IF OLD.status IN ('succeeded', 'failed', 'crashed', 'canceled', 'timed_out',
                      'resource_exhausted') AND NEW IS DISTINCT FROM OLD THEN
        RAISE EXCEPTION 'terminal job attempt is immutable';
    END IF;
    IF NOT (
        NEW.status = OLD.status
        OR (OLD.status = 'queued' AND NEW.status IN ('running', 'canceled', 'timed_out'))
        OR (OLD.status = 'running' AND NEW.status IN (
            'recovering', 'succeeded', 'failed', 'crashed', 'canceled',
            'timed_out', 'resource_exhausted'
        ))
        OR (OLD.status = 'recovering' AND NEW.status IN ('crashed', 'canceled', 'timed_out'))
    ) THEN
        RAISE EXCEPTION 'invalid job attempt state transition';
    END IF;
    RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.job_runtime_jobs_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.organization_id IS DISTINCT FROM OLD.organization_id
       OR NEW.job_id IS DISTINCT FROM OLD.job_id
       OR NEW.semantic_job_key IS DISTINCT FROM OLD.semantic_job_key
       OR NEW.semantic_spec_digest IS DISTINCT FROM OLD.semantic_spec_digest
       OR NEW.capability IS DISTINCT FROM OLD.capability
       OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
        RAISE EXCEPTION 'job identity and semantic specification are immutable';
    END IF;
    IF OLD.cancel_requested_at IS NOT NULL
       AND NEW.cancel_requested_at IS DISTINCT FROM OLD.cancel_requested_at THEN
        RAISE EXCEPTION 'job cancellation request is immutable';
    END IF;
    IF OLD.result_artifact_manifest_digest IS NOT NULL
       AND NEW.result_artifact_manifest_digest
           IS DISTINCT FROM OLD.result_artifact_manifest_digest THEN
        RAISE EXCEPTION 'job result artifact is immutable';
    END IF;
    IF OLD.status IN ('succeeded', 'canceled') AND NEW IS DISTINCT FROM OLD THEN
        RAISE EXCEPTION 'terminal job is immutable';
    END IF;
    IF OLD.status IN ('failed', 'crashed', 'timed_out', 'resource_exhausted')
       AND NEW.status = 'queued' THEN
        IF NEW.attempt_count <> OLD.attempt_count + 1
           OR NEW.cancel_requested_at IS NOT NULL
           OR NEW.result_artifact_manifest_digest IS NOT NULL THEN
            RAISE EXCEPTION 'invalid retry transition';
        END IF;
    ELSIF OLD.status IN ('failed', 'crashed', 'timed_out', 'resource_exhausted')
          AND NEW IS DISTINCT FROM OLD THEN
        RAISE EXCEPTION 'terminal job is immutable outside retry';
    ELSIF NEW.attempt_count <> OLD.attempt_count THEN
        RAISE EXCEPTION 'attempt count may change only during retry';
    END IF;
    IF NOT (
        NEW.status = OLD.status
        OR (OLD.status = 'queued' AND NEW.status IN ('running', 'canceled', 'timed_out'))
        OR (OLD.status = 'running' AND NEW.status IN (
            'recovering', 'succeeded', 'failed', 'crashed', 'canceled',
            'timed_out', 'resource_exhausted'
        ))
        OR (OLD.status = 'recovering' AND NEW.status IN ('crashed', 'canceled', 'timed_out'))
        OR (OLD.status IN ('failed', 'crashed', 'timed_out', 'resource_exhausted')
            AND NEW.status = 'queued')
    ) THEN
        RAISE EXCEPTION 'invalid job state transition';
    END IF;
    RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.market_data_record_stream_event()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    kind TEXT;
    item RECORD;
    range_end TIMESTAMPTZ;
BEGIN
    IF TG_TABLE_NAME = 'market_data_stream_connections' THEN
        IF TG_OP = 'UPDATE' AND NEW.connected = OLD.connected
           AND NEW.collector_pid = OLD.collector_pid THEN RETURN NEW; END IF;
        INSERT INTO market_data_stream_events(market_id,symbol,event_type)
        VALUES (NEW.market_id,NEW.symbol,
            CASE WHEN NEW.connected THEN 'connection_opened' ELSE 'connection_lost' END);
        RETURN NEW;
    END IF;
    IF TG_OP = 'DELETE' THEN item := OLD; ELSE item := NEW; END IF;
    -- Durable per-candle receipts are not user events: keep the batched hot path unchanged.
    IF item.reason = 'ws_recovery' THEN RETURN NULL; END IF;
    range_end := item.end_at;
    IF TG_OP = 'INSERT' THEN kind := 'recovery_queued';
    ELSIF TG_OP = 'DELETE' THEN kind := 'recovery_closed';
    ELSIF NEW.state = 'failed' AND OLD.state <> 'failed' THEN kind := 'recovery_failed';
    ELSIF NEW.start_at > OLD.start_at THEN
        kind := 'recovery_progress'; item := OLD; range_end := NEW.start_at;
    ELSIF NEW.error_code IS NOT NULL AND
          (NEW.error_code IS DISTINCT FROM OLD.error_code OR
           (NEW.attempt > OLD.attempt AND (NEW.attempt & (NEW.attempt - 1)) = 0)) THEN
        kind := 'recovery_waiting';
    ELSE RETURN NULL;
    END IF;
    INSERT INTO market_data_stream_events
        (market_id,symbol,event_type,reason,error_code,attempt,start_at,end_at)
    VALUES (item.market_id,item.symbol,kind,item.reason,
            CASE WHEN kind='recovery_closed' THEN NULL ELSE item.error_code END,
            item.attempt,item.start_at,range_end);
    RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.market_data_submit_batch(org uuid, actor uuid, key uuid, commands jsonb, submitted_at timestamp with time zone)
 RETURNS SETOF market_data_work_requests
 LANGUAGE plpgsql
AS $function$
DECLARE previous JSONB; command JSONB;
BEGIN
    PERFORM 1 FROM identity_memberships m
        JOIN identity_organizations o ON o.organization_id=m.organization_id
        WHERE m.organization_id=org AND m.user_id=actor
          AND m.status='active' AND o.status='active' FOR SHARE OF m,o;
    IF NOT FOUND THEN RAISE EXCEPTION 'active membership required' USING ERRCODE='42501'; END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended(org::text,26004));
    SELECT request INTO previous FROM market_data_work_batches
        WHERE organization_id=org AND batch_key=key;
    IF FOUND THEN
        IF previous <> commands THEN
            RAISE EXCEPTION 'batch key belongs to different work' USING ERRCODE='22023';
        END IF;
    ELSE
        INSERT INTO market_data_work_batches VALUES (org,key,commands,submitted_at);
        FOR command IN SELECT value FROM jsonb_array_elements(commands) LOOP
            INSERT INTO market_data_work_requests
                (job_id,organization_id,actor_user_id,idempotency_key,batch_key,kind,
                 market_id,symbols,start_at,end_at,total_units,state,created_at,updated_at)
            VALUES ((command->>'id')::uuid,org,actor,(command->>'id')::uuid,key,
                    'candle_ingestion',(command->>'market_id')::smallint,
                    jsonb_build_array(command->>'symbol'),(command->>'start_at')::timestamptz,
                    (command->>'end_at')::timestamptz,(command->>'total_units')::integer,
                    'queued',submitted_at,submitted_at);
        END LOOP;
    END IF;
    RETURN QUERY SELECT * FROM market_data_work_requests
        WHERE organization_id=org AND batch_key=key ORDER BY symbols::text,job_id;
END $function$

CREATE OR REPLACE FUNCTION public.market_data_work_record_event()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE event TEXT;
BEGIN
    IF TG_OP = 'INSERT' THEN event := 'queued';
    ELSIF NEW.attempt > OLD.attempt THEN event := 'continued';
    ELSIF NEW.state = 'running' AND OLD.state = 'retry_wait' THEN event := 'recovered';
    ELSIF NEW.state = 'running' AND OLD.started_at IS NULL THEN event := 'started';
    ELSIF OLD.state = 'paused' AND NEW.state IN ('queued','retry_wait') THEN event := 'resumed';
    ELSIF NEW.state = 'retry_wait' AND OLD.state <> 'retry_wait' THEN event := 'retry_scheduled';
    ELSIF NEW.state IN ('pause_requested','paused','cancel_requested','cancelled','succeeded','failed')
          AND OLD.state <> NEW.state THEN event := NEW.state;
    ELSE RETURN NEW;
    END IF;
    INSERT INTO market_data_work_events
        (job_id,organization_id,event_type,occurred_at,state,attempt,completed_units,
         total_units,rows_written,error_code,error_phase,next_retry_at)
    VALUES (NEW.job_id,NEW.organization_id,event,NEW.updated_at,NEW.state,NEW.attempt,
            NEW.completed_units,NEW.total_units,NEW.rows_written,NEW.error_code,
            NEW.error_phase,NEW.next_retry_at);
    -- Bounded per job. Scheduled worker retention also expires inactive histories.
    DELETE FROM market_data_work_events WHERE job_id = NEW.job_id AND event_id < (
        SELECT event_id FROM market_data_work_events WHERE job_id = NEW.job_id
        ORDER BY event_id DESC OFFSET 511 LIMIT 1);
    RETURN NEW;
END $function$
